import { TRADE_PREFERENCES_DEFAULTS } from '../model/types/tradePreferencesSchema';
export const ACCURACY_MODE_TO_FORM = {
    relative: 0,
    legacy: 1,
};
const ACCURACY_MODE_FROM_FORM = {
    0: 'relative',
    1: 'legacy',
};
// Кроки спінера 0.1 / 1 складаються з плаваючою похибкою (76.00000000000001):
// округлюємо до кроку і в стані форми, і перед відправкою.
const FIELD_DECIMALS = {
    trade_auto_open_delay: 0,
    trade_auto_close_delay: 0,
    trade_in_server_side: 0,
    trade_max_lifetime_minutes: 0,
    trade_accuracy_mode: 0,
    minimal_accuracy: 1,
    minimal_move_buy_relative: 0,
    minimal_move_sell_relative: 0,
    minimal_direction_buy_relative: 0,
    minimal_direction_sell_relative: 0,
    reverse_close_buy_enabled: 0,
    reverse_close_buy_move_relative: 0,
    reverse_close_buy_direction_relative: 0,
    reverse_close_sell_enabled: 0,
    reverse_close_sell_move_relative: 0,
    reverse_close_sell_direction_relative: 0,
};
export const roundTo = (value, decimals) => {
    const factor = 10 ** decimals;
    return Math.round(value * factor) / factor;
};
// Округлення одного поля форми до його кроку; невідоме поле — до цілого.
export const roundFormValue = (key, value) => (roundTo(value, FIELD_DECIMALS[key] ?? 0));
export const tradeFormFromServer = (result) => ({
    trade_auto_open_delay: result.trade_auto_open_delay,
    trade_auto_close_delay: result.trade_auto_close_delay,
    trade_in_server_side: result.trade_in_server_side ? 1 : 0,
    trade_max_lifetime_minutes: result.trade_max_lifetime_minutes
        ?? TRADE_PREFERENCES_DEFAULTS.trade_max_lifetime_minutes,
});
export const neuronFormFromServer = (result) => ({
    trade_accuracy_mode: ACCURACY_MODE_TO_FORM[result.trade_accuracy_mode ?? TRADE_PREFERENCES_DEFAULTS.trade_accuracy_mode],
    minimal_accuracy: result.minimal_accuracy,
    minimal_move_buy_relative: result.minimal_move_buy_relative
        ?? TRADE_PREFERENCES_DEFAULTS.minimal_move_buy_relative,
    minimal_move_sell_relative: result.minimal_move_sell_relative
        ?? TRADE_PREFERENCES_DEFAULTS.minimal_move_sell_relative,
    minimal_direction_buy_relative: result.minimal_direction_buy_relative
        ?? TRADE_PREFERENCES_DEFAULTS.minimal_direction_buy_relative,
    minimal_direction_sell_relative: result.minimal_direction_sell_relative
        ?? TRADE_PREFERENCES_DEFAULTS.minimal_direction_sell_relative,
    reverse_close_buy_enabled: (result.reverse_close_buy_enabled ?? TRADE_PREFERENCES_DEFAULTS.reverse_close_buy_enabled) ? 1 : 0,
    reverse_close_buy_move_relative: result.reverse_close_buy_move_relative
        ?? TRADE_PREFERENCES_DEFAULTS.reverse_close_buy_move_relative,
    reverse_close_buy_direction_relative: result.reverse_close_buy_direction_relative
        ?? TRADE_PREFERENCES_DEFAULTS.reverse_close_buy_direction_relative,
    reverse_close_sell_enabled: (result.reverse_close_sell_enabled ?? TRADE_PREFERENCES_DEFAULTS.reverse_close_sell_enabled) ? 1 : 0,
    reverse_close_sell_move_relative: result.reverse_close_sell_move_relative
        ?? TRADE_PREFERENCES_DEFAULTS.reverse_close_sell_move_relative,
    reverse_close_sell_direction_relative: result.reverse_close_sell_direction_relative
        ?? TRADE_PREFERENCES_DEFAULTS.reverse_close_sell_direction_relative,
});
export const toTradePreferencesRequest = (values) => ({
    trade_auto_open_delay: roundTo(values.trade_auto_open_delay, 0),
    trade_auto_close_delay: roundTo(values.trade_auto_close_delay, 0),
    trade_in_server_side: Boolean(values.trade_in_server_side),
    trade_max_lifetime_minutes: roundTo(values.trade_max_lifetime_minutes, 0),
});
export const toNeuronPreferencesRequest = (values) => ({
    trade_accuracy_mode: ACCURACY_MODE_FROM_FORM[values.trade_accuracy_mode],
    minimal_accuracy: roundTo(values.minimal_accuracy, FIELD_DECIMALS.minimal_accuracy),
    minimal_move_buy_relative: roundTo(values.minimal_move_buy_relative, 0),
    minimal_move_sell_relative: roundTo(values.minimal_move_sell_relative, 0),
    minimal_direction_buy_relative: roundTo(values.minimal_direction_buy_relative, 0),
    minimal_direction_sell_relative: roundTo(values.minimal_direction_sell_relative, 0),
    reverse_close_buy_enabled: Boolean(values.reverse_close_buy_enabled),
    reverse_close_buy_move_relative: roundTo(values.reverse_close_buy_move_relative, 0),
    reverse_close_buy_direction_relative: roundTo(values.reverse_close_buy_direction_relative, 0),
    reverse_close_sell_enabled: Boolean(values.reverse_close_sell_enabled),
    reverse_close_sell_move_relative: roundTo(values.reverse_close_sell_move_relative, 0),
    reverse_close_sell_direction_relative: roundTo(values.reverse_close_sell_direction_relative, 0),
});
